WITH ValidSuppliers AS (SELECT *, CONCAT_WS('-', city, country) AS city_country_key FROM suppliers WHERE rating <= 1.9 AND (country = 'US' OR country IN ('UK', 'TH', 'JP'))), agg AS (SELECT city, ROUND((100 * SUM(CASE WHEN city = 'London' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_london, COUNT(DISTINCT rating) AS unique_countrys FROM ValidSuppliers GROUP BY city) SELECT city, pct_london, unique_countrys FROM agg ORDER BY pct_london
